import torch
def fun2(v):
return torch.tensor([1])*max(v,100)
@torch.compile(dynamic = True)
def fun(a, b):
return torch.tensor([1])+ fun2(v = max(a, b) if a and b else b)
fun(1000, 12)
fun(100, 12)
